from taf.ue.plugin.mtk.commands import SetDefaultFilter, GetPlatformInfo, PortsReady


class MaceSetDefaultFilter(SetDefaultFilter):

    def __init__(self, mace, filter_name=None):
        super(MaceSetDefaultFilter, self).__init__(filter_name=filter_name)
        self._mace = mace

    def execute(self):
        return self._mace.set_filter(filter_name=self.filter_name)


class MaceGetPlatformInfo(GetPlatformInfo):
    def __init__(self, mace):
        super(MaceGetPlatformInfo, self).__init__()
        self._mace = mace

    def execute(self):
        return self._mace.get_platform_information()


class MaceGetSoftwareVersion(object):
    def __init__(self, mace):
        self._info_cmd = MaceGetPlatformInfo(mace)

    def execute(self):
        return self._info_cmd.execute()['SW']


class MacePortsReady(PortsReady):
    def __init__(self, mace):
        super(MacePortsReady, self).__init__()
        self._mace = mace

    def execute(self):
        return self._mace.is_com_ports_ready()
